import{_ as e}from"./chunks/100.Bym1HttY.js";import{_ as o,o as i,c as n,ak as a}from"./chunks/framework.Ba6sv-31.js";const r="/projects/AiBlockSensor/en/latest/assets/1.D09e_zyE.webp",s="/projects/AiBlockSensor/en/latest/assets/2.Dcg_BejG.webp",l="/projects/AiBlockSensor/en/latest/assets/1.BsumoVxw.webp",c="/projects/AiBlockSensor/en/latest/assets/2.Cl3r7F88.webp",d="/projects/AiBlockSensor/en/latest/assets/3.DtDgvM0m.webp",h="/projects/AiBlockSensor/en/latest/assets/4.Xm1ewtlL.webp",g="/projects/AiBlockSensor/en/latest/assets/3.BJ3xeSOp.webp",p="/projects/AiBlockSensor/en/latest/assets/4.C3FVDjai.webp",m="/projects/AiBlockSensor/en/latest/assets/5.BR9Gst5g.webp",u="/projects/AiBlockSensor/en/latest/assets/1.BsumoVxw.webp",A="/projects/AiBlockSensor/en/latest/assets/2.CW1SKy4b.webp",y="/projects/AiBlockSensor/en/latest/assets/3.CTm8gXic.webp",f="/projects/AiBlockSensor/en/latest/assets/4.CWjGoygI.webp",w="data:image/png;base64,",x="/projects/AiBlockSensor/en/latest/assets/6.5H_LWQh4.webp",b="/projects/AiBlockSensor/en/latest/assets/7.DiO0y1Kv.webp",I="/projects/AiBlockSensor/en/latest/assets/8.Deakagdb.webp",j=JSON.parse('{"title":"18. AI Voice Interaction Module","description":"","frontmatter":{},"headers":[],"relativePath":"docs/18. AI Voice Interaction Module.md","filePath":"docs/18. AI Voice Interaction Module.md"}'),k={name:"docs/18. AI Voice Interaction Module.md"};function _(B,t,v,q,M,C){return i(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="_18-ai-voice-interaction-module" tabindex="-1">18. AI Voice Interaction Module <a class="header-anchor" href="#_18-ai-voice-interaction-module" aria-label="Permalink to &quot;18. AI Voice Interaction Module&quot;">​</a></h1><h2 id="_18-1-introduction" tabindex="-1">18.1 Introduction <a class="header-anchor" href="#_18-1-introduction" aria-label="Permalink to &quot;18.1 Introduction&quot;">​</a></h2><p>This section introduces the AI voice interaction module, which provides speech recognition and voice broadcasting powered by the CI1302 neural processor. The module incorporates offline neural network acceleration and dedicated audio signal processing hardware, extracting spoken commands accurately through deep noise reduction. It activates via a designated wake-up word, entering an active listening state for subsequent voice recognition.</p><p>Featuring straightforward operation and reliable speech recognition, this module serves diverse applications, including smart home prototypes, conversational bots, educational robots, and vehicle dispatch terminals.</p><img loading="lazy" height="723" width="929" src="'+r+'" class="common_img" style="width:300px;"><h2 id="_18-2-technical-specifications" tabindex="-1">18.2 Technical Specifications <a class="header-anchor" href="#_18-2-technical-specifications" aria-label="Permalink to &quot;18.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Recognition mode</td><td style="text-align:center;">Command-word wake-up</td></tr><tr><td style="text-align:center;">Recognition range</td><td style="text-align:center;">1 ~ 5 m</td></tr><tr><td style="text-align:center;">Recognition capacity</td><td style="text-align:center;">≤255 words or short phrases</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">27.0 × 11.7 × 9.8 mm</td></tr></tbody></table><h2 id="_18-3-hardware-interface-description" tabindex="-1">18.3 Hardware Interface Description <a class="header-anchor" href="#_18-3-hardware-interface-description" aria-label="Permalink to &quot;18.3 Hardware Interface Description&quot;">​</a></h2><img loading="lazy" height="860" width="1318" src="'+s+'" class="common_img" style="width:500px;"><p>The corresponding functions are listed in the table below:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Component</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Firmware flashing port</td><td style="text-align:center;">Connects to a computer to flash module firmware</td></tr><tr><td style="text-align:center;">Block mounting holes</td><td style="text-align:center;">Mounts onto building block structures for mechanical fixation</td></tr><tr><td style="text-align:center;">Speaker</td><td style="text-align:center;">Outputs audio and broadcasts voice command responses</td></tr><tr><td style="text-align:center;">Microphone</td><td style="text-align:center;">Collects ambient audio for speech recognition</td></tr><tr><td style="text-align:center;">Reset button (RST)</td><td style="text-align:center;">Reboots the module when pressed to resolve unexpected halts</td></tr><tr><td style="text-align:center;">Module cable port</td><td style="text-align:center;">Connects a 4-pin module cable for power supply and signal communication</td></tr></tbody></table><h2 id="_18-4-voice-interaction-testing" tabindex="-1">18.4 Voice Interaction Testing <a class="header-anchor" href="#_18-4-voice-interaction-testing" aria-label="Permalink to &quot;18.4 Voice Interaction Testing&quot;">​</a></h2><ol><li>Connect the Type-C port on top of the AI voice interaction module to a computer port or phone charger using a USB cable for power supply.</li></ol><img loading="lazy" height="470" width="430" src="'+l+'" class="common_img" style="width:300px;"><ol start="2"><li>Taking the command word <strong>Go straight</strong> as an example for speech testing, first state the wake-up word <strong>Hello Hiwonder</strong> to activate the module. When the module replies with <strong>I&#39;m here</strong>, it indicates readiness for voice recognition.</li></ol><img loading="lazy" height="270" width="211" src="'+c+'" class="common_img" style="width:300px;"><ol start="3"><li>Next, speak the command word <strong>Go straight</strong> to the module to trigger the corresponding voice response.</li></ol><img loading="lazy" height="270" width="211" src="'+d+'" class="common_img" style="width:300px;"><ol start="4"><li>Speaking any of the following command words also prompts WonderEcho to broadcast the corresponding response phrase.</li></ol><img loading="lazy" height="531" width="802" src="'+h+'" class="common_img" style="width:500px;"><h2 id="_18-5-hands-on-project" tabindex="-1">18.5 Hands-On Project <a class="header-anchor" href="#_18-5-hands-on-project" aria-label="Permalink to &quot;18.5 Hands-On Project&quot;">​</a></h2><h3 id="_18-5-1-project-introduction" tabindex="-1">18.5.1 Project Introduction <a class="header-anchor" href="#_18-5-1-project-introduction" aria-label="Permalink to &quot;18.5.1 Project Introduction&quot;">​</a></h3><p>This project programs the AI voice interaction module to poll and process spoken commands continuously in a loop. When the module detects specific voice commands, the controller prints corresponding feedback messages to the serial monitor. Working through this project covers module port initialization, voice result polling, and multi-branch conditional logic.</p><h3 id="_18-5-2-hardware-wiring" tabindex="-1">18.5.2 Hardware Wiring <a class="header-anchor" href="#_18-5-2-hardware-wiring" aria-label="Permalink to &quot;18.5.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the AI voice interaction module to port <strong>A</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="304" width="972" src="'+g+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This module supports connection to any port among A, B, C, or D on the controller. Ensure that the port selected in the program matches the physical wiring.</strong></p></div><h3 id="_18-5-3-adding-extensions" tabindex="-1">18.5.3 Adding Extensions <a class="header-anchor" href="#_18-5-3-adding-extensions" aria-label="Permalink to &quot;18.5.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>WonderEcho speech module</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+p+'" class="common_img" style="width:800px;"><h3 id="_18-5-4-complete-program-and-analysis" tabindex="-1">18.5.4 Complete Program and Analysis <a class="header-anchor" href="#_18-5-4-complete-program-and-analysis" aria-label="Permalink to &quot;18.5.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Upon power-on, initialize the hardware port of the AI voice interaction module to port A.</p></li><li><p>In the main program, continuously refresh and read recognition results from the AI voice interaction module inside a loop:</p><ul><li><p>Update and retrieve speech recognition results.</p></li><li><p>When the command <code>go straight</code> is recognized, print <code>Go forward!</code> to the serial monitor.</p></li><li><p>When the command <code>go backward</code> is recognized, print <code>Go back!</code> to the serial monitor, then continuously repeat the voice command detection loop.</p></li></ul></li></ol><img loading="lazy" height="544" width="673" src="'+m+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1fLfLXEVjSMZdojOq7C44xJqZIBm4MDem?usp=sharing" target="_blank" rel="noreferrer">Program Files/ 21 AI Voice Module.sb3</a>.</strong></p></div><h3 id="_18-5-5-program-upload" tabindex="-1">18.5.5 Program Upload <a class="header-anchor" href="#_18-5-5-program-upload" aria-label="Permalink to &quot;18.5.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"><h3 id="_18-5-6-program-outcome" tabindex="-1">18.5.6 Program Outcome <a class="header-anchor" href="#_18-5-6-program-outcome" aria-label="Permalink to &quot;18.5.6 Program Outcome&quot;">​</a></h3><p>After uploading the program, the module powers on and completes initialization. Once awakened with <strong>Hello Hiwonder</strong>, speaking <code>go straight</code> prompts the serial monitor to print <code>Go forward!</code>. Speaking <code>go backward</code> prints <code>Go back!</code>. The system continuously listens for incoming voice commands.</p><h2 id="_18-6-firmware-flashing" tabindex="-1">18.6 Firmware Flashing <a class="header-anchor" href="#_18-6-firmware-flashing" aria-label="Permalink to &quot;18.6 Firmware Flashing&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The module comes pre-flashed with factory firmware, so reflashing is not required under normal circumstances. This section is intended only for firmware updates or recovery when firmware corruption occurs.</strong></p></div><ol><li>Connect the Type-C port on top of the AI voice interaction module to a computer using a USB cable.</li></ol><img loading="lazy" height="470" width="430" src="'+u+'" class="common_img" style="width:300px;"><ol start="2"><li>Open the <strong>PACK_UPDATE_TOOL</strong> file located inside the <strong><a href="https://drive.google.com/drive/folders/1U_jJhR2uB_lzHK8nNah0x_-t4d3ntgvu?usp=sharing" target="_blank" rel="noreferrer">Appendix File\\02 AI Voice Module Files\\Flashing-tool</a></strong> folder.</li></ol><img loading="lazy" height="395" width="669" src="'+A+'" class="common_img" style="width:500px;"><ol start="3"><li>Select the <strong>CI1302</strong> chip, then click <strong>Update</strong>.</li></ol><img loading="lazy" height="492" width="652" src="'+y+'" class="common_img" style="width:500px;"><ol start="4"><li>Click <strong>Select firmware</strong> to choose the bin firmware file to flash: navigate to the <strong>WonderEcho Flash‑firmware 20260901.bin</strong> file inside the <strong><a href="https://drive.google.com/drive/folders/1GHWgD9G__eEzLy5gMNfgaGd3_zZsz2ri?usp=sharing" target="_blank" rel="noreferrer">Appendix File\\02 AI Voice Module Files\\02 Flashing Firmware</a></strong> folder.</li></ol><img loading="lazy" height="248" width="836" src="'+f+'" class="common_img" style="width:500px;"><img loading="lazy" height="46" width="386" src="'+w+'" class="common_img" style="width:500px;"><ol start="5"><li>Locate the corresponding serial port and click to select it.</li></ol><img loading="lazy" height="633" width="843" src="'+x+'" class="common_img" style="width:500px;"><ol start="6"><li>Press the <strong>RST</strong> button on the voice interaction module to enter flashing mode, then wait for the flashing process to complete successfully.</li></ol><img loading="lazy" height="1057" width="700" src="'+b+'" class="common_img" style="width:300px;"><img loading="lazy" height="217" width="838" src="'+I+'" class="common_img" style="width:500px;">',55)])])}const E=o(k,[["render",_]]);export{j as __pageData,E as default};
